#include <bits/stdc++.h>
using namespace std;

// 高精度：十进制、低位在前，反复乘一个小整数
vector<int> mulSmall(vector<int> a, int b) {
    vector<int> res(a.size(), 0);
    long long carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        long long cur = (long long)a[i] * b + carry;
        res[i] = (int)(cur % 10);
        carry = cur / 10;
    }
    while (carry) { res.push_back((int)(carry % 10)); carry /= 10; }
    return res;
}

int reachSize[10];

int main() {
    string n;
    int k;
    cin >> n >> k;
    vector<pair<int, int>> rules(k);
    for (auto &r : rules) cin >> r.first >> r.second;

    // 每个数字独立求可达集：reach[d] 从 {d} 开始松弛
    for (int d = 0; d < 10; d++) {
        bool has[10] = {false};
        has[d] = true;
        for (int round = 0; round < 10; round++) {
            bool changed = false;
            for (auto &r : rules) {
                if (has[r.first] && !has[r.second]) {
                    has[r.second] = true;
                    changed = true;
                }
            }
            if (!changed) break;
        }
        int s = 0;
        for (int i = 0; i < 10; i++) if (has[i]) s++;
        reachSize[d] = s;
    }

    vector<int> ans(1, 1);
    for (size_t i = 0; i < n.size(); i++) {
        ans = mulSmall(ans, reachSize[n[i] - '0']);
    }

    for (int i = (int)ans.size() - 1; i >= 0; i--) cout << ans[i];
    cout << "\n";
    return 0;
}
